use base64::{engine::general_purpose::STANDARD as BASE64, Engine as _};
use rusqlite::{params, Connection, OptionalExtension};
use serde::Deserialize;
use std::{collections::HashMap, env, net::SocketAddr, path::Path as FsPath};

const QUIZZY_CSS: &str = include_str!("../assets/quizzy.css");
static FONT_BYTES: &[u8] = include_bytes!("../assets/Inter-latin.woff2");

#[derive(Clone)]
struct AppState {
    db_path: String,
    mod_user: String,
    mod_pass: String,
