fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#x27;")
}

fn db_connect(state: &AppState) -> Result<Connection, rusqlite::Error> {
    let conn = Connection::open(&state.db_path)?;
    conn.execute_batch("PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL;")?;
    Ok(conn)
}

fn init_db(db_path: &str) {
    if let Some(parent) = FsPath::new(db_path).parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let conn = Connection::open(db_path).expect("open db");
    conn.execute_batch(
        "
        PRAGMA journal_mode=WAL;
        PRAGMA foreign_keys=ON;
        CREATE TABLE IF NOT EXISTS quizzes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
        CREATE TABLE IF NOT EXISTS questions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            quiz_id INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
            body TEXT NOT NULL,
            active INTEGER NOT NULL DEFAULT 1,
            position INTEGER NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
        CREATE TABLE IF NOT EXISTS options (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
            body TEXT NOT NULL,
            is_correct INTEGER NOT NULL DEFAULT 0,
            position INTEGER NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_questions_quiz ON questions(quiz_id, position);
        CREATE INDEX IF NOT EXISTS idx_options_q ON options(question_id, position);
        ",
    )
    .expect("migrate");
}

#[derive(Debug)]
struct Quiz {
    id: i64,
    title: String,
}
#[derive(Debug)]
struct Question {
    id: i64,
    quiz_id: i64,
    body: String,
    active: bool,
    position: i64,
}
#[derive(Debug)]
struct OptionItem {
    id: i64,
    question_id: i64,
    body: String,
    is_correct: bool,
    position: i64,
}

fn list_quizzes(conn: &Connection) -> Vec<Quiz> {
    let mut stmt = conn
        .prepare("SELECT id, title FROM quizzes ORDER BY id ASC")
        .unwrap();
    let rows = stmt
        .query_map([], |row| {
            Ok(Quiz {
                id: row.get(0)?,
                title: row.get(1)?,
            })
        })
        .unwrap();
    rows.filter_map(|r| r.ok()).collect()
}

fn get_quiz(conn: &Connection, id: i64) -> Option<Quiz> {
    conn.query_row("SELECT id, title FROM quizzes WHERE id=?1", params![id], |row| {
        Ok(Quiz {
            id: row.get(0)?,
            title: row.get(1)?,
        })
    })
    .optional()
    .unwrap()
}

fn count_questions(conn: &Connection, quiz_id: i64) -> (i64, i64) {
    let total: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM questions WHERE quiz_id=?1",
            params![quiz_id],
            |r| r.get(0),
        )
        .unwrap_or(0);
    let active: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM questions WHERE quiz_id=?1 AND active=1",
            params![quiz_id],
            |r| r.get(0),
        )
        .unwrap_or(0);
    (total, active)
}

fn list_questions(conn: &Connection, quiz_id: i64) -> Vec<Question> {
    let mut stmt = conn
        .prepare("SELECT id, quiz_id, body, active, position FROM questions WHERE quiz_id=?1 ORDER BY position ASC, id ASC")
        .unwrap();
    let rows = stmt
        .query_map(params![quiz_id], |row| {
            let active_int: i64 = row.get(3)?;
            Ok(Question {
                id: row.get(0)?,
                quiz_id: row.get(1)?,
                body: row.get(2)?,
                active: active_int != 0,
                position: row.get(4)?,
            })
        })
        .unwrap();
    rows.filter_map(|r| r.ok()).collect()
}

fn get_question(conn: &Connection, quiz_id: i64, qid: i64) -> Option<Question> {
    conn.query_row(
        "SELECT id, quiz_id, body, active, position FROM questions WHERE id=?1 AND quiz_id=?2",
        params![qid, quiz_id],
        |row| {
            let active_int: i64 = row.get(3)?;
            Ok(Question {
                id: row.get(0)?,
                quiz_id: row.get(1)?,
                body: row.get(2)?,
                active: active_int != 0,
                position: row.get(4)?,
            })
        },
    )
    .optional()
    .unwrap()
}

fn list_options(conn: &Connection, question_id: i64) -> Vec<OptionItem> {
    let mut stmt = conn
        .prepare("SELECT id, question_id, body, is_correct, position FROM options WHERE question_id=?1 ORDER BY position ASC, id ASC")
        .unwrap();
    let rows = stmt
        .query_map(params![question_id], |row| {
            let c: i64 = row.get(3)?;
            Ok(OptionItem {
                id: row.get(0)?,
                question_id: row.get(1)?,
                body: row.get(2)?,
                is_correct: c != 0,
                position: row.get(4)?,
            })
        })
        .unwrap();
    rows.filter_map(|r| r.ok()).collect()
}

fn letter_for(i: usize) -> String {
    if i < 26 {
        ((b'A' + i as u8) as char).to_string()
    } else {
        format!("{}", i + 1)
    }
}

