async fn update_question_handler(
    State(state): State<AppState>,
    Path((id, qid)): Path<(i64, i64)>,
    Form(form): Form<HashMap<String, String>>,
) -> impl IntoResponse {
    let conn = db_connect(&state).unwrap();
    let Some(quiz) = get_quiz(&conn, id) else {
        return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Quiz not found</h1>"))).into_response();
    };
    let Some(_q) = get_question(&conn, id, qid) else {
        return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Question not found</h1>"))).into_response();
    };
    let (body, active, filtered, raw_keep) = parse_question_form(&form);
    let mut errors: Vec<String> = Vec::new();
    if body.trim().is_empty() {
        errors.push("Question can't be blank".to_string());
    }
    if filtered.len() < 2 {
        errors.push("Add at least two options".to_string());
    }
    if filtered.iter().filter(|(_, c)| *c).count() == 0 {
        errors.push("Mark at least one option as correct".to_string());
    }
    if !errors.is_empty() {
        let rows = if raw_keep.is_empty() {
            vec![
                (String::new(), false),
                (String::new(), false),
                (String::new(), false),
                (String::new(), false),
            ]
        } else {
            raw_keep
        };
        let html = render_question_form(
            &quiz,
            &format!("/moderate/quizzes/{}/questions/{}", id, qid),
            "Edit question",
            &body,
            active,
            &rows,
            &errors,
        );
        return Html(html).into_response();
    }
    conn.execute(
        "UPDATE questions SET body=?1, active=?2 WHERE id=?3",
        params![body.trim(), if active { 1 } else { 0 }, qid],
    )
    .unwrap();
    conn.execute("DELETE FROM options WHERE question_id=?1", params![qid])
        .unwrap();
    for (i, (text, correct)) in filtered.iter().enumerate() {
        conn.execute(
            "INSERT INTO options (question_id, body, is_correct, position) VALUES (?1, ?2, ?3, ?4)",
            params![qid, text, if *correct { 1 } else { 0 }, i as i64],
        )
        .unwrap();
    }
    Redirect::to(&format!("/moderate/quizzes/{}", id)).into_response()
}

