}

async fn toggle_active_handler(
    State(state): State<AppState>,
    Path((id, qid)): Path<(i64, i64)>,
    req: axum::extract::Request,
) -> impl IntoResponse {
    // Parse form manually to handle empty body
    let (_parts, body) = req.into_parts();
    let bytes = axum::body::to_bytes(body, 1024 * 1024).await.unwrap_or_default();
    let body_str = String::from_utf8_lossy(&bytes).to_string();
    // Parse urlencoded
    let mut active_present = false;
    // Also need to handle _form? Just check for active=
    // Simple parse: split & then =
    for pair in body_str.split('&') {
        let (k, _v) = pair.split_once('=').unwrap_or((pair, ""));
        // decode percent? For our purpose, k == "active" is enough (no encoding)
        // Use serde_urlencoded for robustness? Do manual decode of + and %?
        let key = percent_decode(k);
        if key == "active" {
            active_present = true;
            break;
        }
    }
    // If body empty and no active, it means unchecked. But what if request had no body at all?
    // That's also unchecked. Good.
    // However, if the form was submitted with checkbox checked, active_present will be true.
    // If unchecked, false.
    // Edge: if client sends no Content-Type and empty, still false.
    let conn = db_connect(&state).unwrap();
    // Verify question belongs to quiz
    if get_question(&conn, id, qid).is_none() {
        return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Question not found</h1>"))).into_response();
    }
    conn.execute(
        "UPDATE questions SET active=?1 WHERE id=?2",
        params![if active_present { 1 } else { 0 }, qid],
    )
    .unwrap();
    Redirect::to(&format!("/moderate/quizzes/{}", id)).into_response()
}

fn percent_decode(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '+' {
            out.push(' ');
        } else if c == '%' {
            let h1 = chars.next().unwrap_or('0');
            let h2 = chars.next().unwrap_or('0');
            let hex = format!("{}{}", h1, h2);
            if let Ok(b) = u8::from_str_radix(&hex, 16) {
                out.push(b as char);
            } else {
                out.push('%');
                out.push(h1);
                out.push(h2);
            }
        } else {
            out.push(c);
        }
    }
    out
}

// ---------- preview ----------
#[derive(Deserialize, Debug)]
struct PreviewQuery {
    q: Option<usize>,
    score: Option<i32>,
    picked: Option<i64>,
}

#[derive(Deserialize, Debug)]
struct AnswerQuery {
    q: Option<usize>,
    score: Option<i32>,
}

#[derive(Deserialize, Debug)]
struct ResultQuery {
    score: Option<i32>,
}

async fn preview_show_handler(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    Query(q): Query<PreviewQuery>,
) -> impl IntoResponse {
    let conn = db_connect(&state).unwrap();
    let Some(quiz) = get_quiz(&conn, id) else {
        return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Quiz not found</h1>"))).into_response();
    };
    let all = list_questions(&conn, id);
    let active_qs: Vec<Question> = all.into_iter().filter(|qq| qq.active).collect();
    let total = active_qs.len();
    if total == 0 {
        let content = format!(
            r#"<div class="play-question__num">Question 0 of 0</div><div class="play-question__body">No active questions</div><div class="play-status play-status--neutral">Add questions and mark them active to preview.</div><div class="buttons" style="margin-top:20px;justify-content:center"><a class="btn btn--pink" href="/moderate/quizzes/{}/preview">Start over</a><a class="btn btn--light" href="/moderate/quizzes/{}">Back to quiz</a></div>"#,
            id, id
        );
        return Html(preview_layout(&quiz.title, id, &content)).into_response();
    }
    // If no q param, redirect to q=0
    if q.q.is_none() {
        return Redirect::to(&format!("/moderate/quizzes/{}/preview?q=0&score=0", id)).into_response();
    }
    let q_idx = q.q.unwrap_or(0);
    let score = q.score.unwrap_or(0).max(0);
    if q_idx >= total {
        // out of bounds -> redirect to result
        return Redirect::to(&format!(
            "/moderate/quizzes/{}/preview/result?score={}",
            id, score
        ))
        .into_response();
    }
    let current = &active_qs[q_idx];
    let opts = list_options(&conn, current.id);
    if let Some(picked_id) = q.picked {
        // answered state
        let picked_opt = opts.iter().find(|o| o.id == picked_id);
        let is_right = picked_opt.map(|o| o.is_correct).unwrap_or(false);
        let status_text = if is_right { "Correct!" } else { "Wrong!" };
        let status_class = if is_right {
            "play-status--right"
        } else {
            "play-status--wrong"
        };
        let mut ohtml = String::new();
        for (i, o) in opts.iter().enumerate() {
            let letter = letter_for(i);
            let mut cls = String::from("play-option");
            if o.is_correct {
                cls.push_str(" is-correct");
            }
            if o.id == picked_id {
                cls.push_str(" is-picked");
            }
            let mark = if o.is_correct {
                r#"<span class="play-option__mark">✓</span>"#
            } else {
                ""
            };
            ohtml.push_str(&format!(
                r#"<div class="{}"><span class="play-option__letter">{}</span><span class="play-option__title">{}</span>{}</div>"#,
                cls,
                letter,
                html_escape(&o.body),
                mark
            ));
        }
        let next_html = if q_idx + 1 < total {
            format!(
                r#"<a class="btn btn--pink" href="/moderate/quizzes/{}/preview?q={}&score={}">Next question</a>"#,
                id,
                q_idx + 1,
                score
            )
        } else {
            format!(
                r#"<a class="btn btn--pink" href="/moderate/quizzes/{}/preview/result?score={}">See score</a>"#,
                id, score
            )
        };
        let content = format!(
            r#"<div class="play-question__num">Question {} of {}</div><div class="play-question__body">{}</div><div class="play-options is-locked is-revealed">{}</div><div class="play-status {}">{}</div><div class="play-score"><span>Score: {}/{}</span></div><div class="buttons" style="margin-top:20px">{}</div><div class="buttons" style="margin-top:12px"><a class="btn btn--ghost" href="/moderate/quizzes/{}/preview">Start over</a></div>"#,
            q_idx + 1,
            total,
            html_escape(&current.body),
            ohtml,
            status_class,
            status_text,
            score,
            total,
            next_html,
            id
        );
        Html(preview_layout(&quiz.title, id, &content)).into_response()
    } else {
        // unanswered
        let mut ohtml = String::new();
        for (i, o) in opts.iter().enumerate() {
            let letter = letter_for(i);
            ohtml.push_str(&format!(
                r#"<form method="post" action="/moderate/quizzes/{}/preview/answer?q={}&score={}"><button class="play-option" type="submit" name="option_id" value="{}"><span class="play-option__letter">{}</span><span class="play-option__title">{}</span></button></form>"#,
                id,
                q_idx,
                score,
                o.id,
                letter,
                html_escape(&o.body)
            ));
        }
        let content = format!(
            r#"<div class="play-question__num">Question {} of {}</div><div class="play-question__body">{}</div><div class="play-options">{}</div><div class="buttons" style="margin-top:20px"><a class="btn btn--ghost" href="/moderate/quizzes/{}/preview">Start over</a></div>"#,
            q_idx + 1,
            total,
            html_escape(&current.body),
            ohtml,
            id
        );
        Html(preview_layout(&quiz.title, id, &content)).into_response()
    }
}

async fn preview_answer_handler(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    Query(q): Query<AnswerQuery>,
    req: axum::extract::Request,
) -> impl IntoResponse {
    let conn = db_connect(&state).unwrap();
    let Some(_quiz) = get_quiz(&conn, id) else {
        return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Quiz not found</h1>"))).into_response();
    };
    let all = list_questions(&conn, id);
    let active_qs: Vec<Question> = all.into_iter().filter(|qq| qq.active).collect();
    let total = active_qs.len();
    let q_idx = q.q.unwrap_or(0);
    let score = q.score.unwrap_or(0).max(0);
    if q_idx >= total {
        return Redirect::to(&format!(
            "/moderate/quizzes/{}/preview/result?score={}",
            id, score
        ))
        .into_response();
    }
    // parse option_id from body
    let (_parts, body) = req.into_parts();
    let bytes = axum::body::to_bytes(body, 1024 * 1024).await.unwrap_or_default();
    let body_str = String::from_utf8_lossy(&bytes).to_string();
    let mut option_id: Option<i64> = None;
    for pair in body_str.split('&') {
        if pair.is_empty() {
            continue;
        }
        let (k, v) = pair.split_once('=').unwrap_or((pair, ""));
        let key = percent_decode(k);
        let val = percent_decode(v);
        if key == "option_id" {
            if let Ok(n) = val.parse::<i64>() {
                option_id = Some(n);
            }
        }
    }
    let Some(oid) = option_id else {
        // no option, redirect back to same question
        return Redirect::to(&format!(
            "/moderate/quizzes/{}/preview?q={}&score={}",
            id, q_idx, score
        ))
        .into_response();
    };
    let current = &active_qs[q_idx];
    let opts = list_options(&conn, current.id);
    let picked = opts.iter().find(|o| o.id == oid);
    let is_correct = picked.map(|o| o.is_correct).unwrap_or(false);
    let new_score = if is_correct { score + 1 } else { score };
    Redirect::to(&format!(
        "/moderate/quizzes/{}/preview?q={}&score={}&picked={}",
        id, q_idx, new_score, oid
    ))
    .into_response()
}

async fn preview_result_handler(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    Query(q): Query<ResultQuery>,
) -> impl IntoResponse {
    let conn = db_connect(&state).unwrap();
    let Some(quiz) = get_quiz(&conn, id) else {
        return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Quiz not found</h1>"))).into_response();
    };
    let all = list_questions(&conn, id);
    let total = all.into_iter().filter(|qq| qq.active).count();
    let score = q.score.unwrap_or(0).max(0);
    let content = format!(
        r#"<div class="result-card"><div class="result-card__place">🏆</div><div class="result-card__label">Preview finished</div><div class="result-card__score">Score: {}/{}</div><div class="buttons" style="justify-content:center;margin-top:24px"><a class="btn btn--pink" href="/moderate/quizzes/{}/preview">Start over</a><a class="btn btn--ghost" href="/moderate/quizzes/{}">Back to quiz</a></div></div>"#,
        score, total, id, id
    );
    Html(preview_layout(&quiz.title, id, &content)).into_response()
}

