        .route(
            "/moderate/quizzes/:id/questions",
            axum::routing::post(create_question_handler),
        )
        .route(
            "/moderate/quizzes/:id/questions/:qid/edit",
            get(edit_question_form_handler),
        )
        .route(
            "/moderate/quizzes/:id/questions/:qid",
            axum::routing::post(update_question_handler),
        )
        .route(
            "/moderate/quizzes/:id/questions/:qid/delete",
            axum::routing::post(delete_question_handler),
        )
        .route(
            "/moderate/quizzes/:id/questions/:qid/move-up",
            axum::routing::post(move_up_handler),
