        )
        .route(
            "/moderate/quizzes/:id/questions/:qid/active",
            axum::routing::post(toggle_active_handler),
        )
        .route(
            "/moderate/quizzes/:id/questions/:qid/toggle-active",
            axum::routing::post(toggle_active_handler),
        )
        .route(
            "/moderate/quizzes/:id/preview",
            get(preview_show_handler),
        )
        .route(
            "/moderate/quizzes/:id/preview/answer",
            axum::routing::post(preview_answer_handler),
        )
        .route(
            "/moderate/quizzes/:id/preview/result",
            get(preview_result_handler),
        )
        .layer(axum::middleware::from_fn_with_state(state.clone(), auth_middleware))
        .with_state(state);

    let addr = SocketAddr::from(([0, 0, 0, 0], port));
    println!("Quizzy listening on {}", addr);
    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
    axum::serve(listener, app).await.unwrap();
}
